contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositA, uint256 depositB) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositA) + (depositB)); require(depositA <= 1000000000000000000000000000000); require(depositB <= 1000000000000000000000000000000);
        require(address(this).balance >= depositA + depositB);
        uint256 beforeBalance = address(c).balance;
        c.deposit{value: depositA}(); if (__ESBMC_reverted()) return;
        c.deposit{value: depositB}(); if (__ESBMC_reverted()) return;
        uint256 afterBalance = address(c).balance;
        assert(afterBalance == beforeBalance + depositA + depositB);
    }
    receive() external payable {}
}

