// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositA, uint256 depositB) internal {
        depositA = bound(depositA, 0, 1000000000000000000000000000000);
        depositB = bound(depositB, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositA + depositB);
        uint256 beforeBalance = address(c).balance;
        try c.deposit{value: depositA}() {} catch { return; }
        try c.deposit{value: depositB}() {} catch { return; }
        uint256 afterBalance = address(c).balance;
        assertTrue(afterBalance == beforeBalance + depositA + depositB);
    }

    function testFuzz_run(uint256 depositA, uint256 depositB) public {
        _run(depositA, depositB);
    }

    receive() external payable {}
}
